class TestTestStrategy:
    """Validates abstract base class contract and instantiation guards."""

    def test_cannot_instantiate_abstract(self):
        """Abstract class must raise TypeError on direct instantiation."""
        with pytest.raises(TypeError):
            TestStrategy()

    def test_concrete_subclass_works(self, base_strategy):
        """Concrete subclass must instantiate and generate correctly."""
