    def test_generate_not_implemented_raises(self):
        """Subclass without generate() must raise NotImplementedError."""
        class IncompleteStrategy(TestStrategy):
            pass

        instance = IncompleteStrategy()
        with pytest.raises(NotImplementedError):
            instance.generate(None)

    def test_generate_returns_list(self, base_strategy):
        """generate() must always return a list."""
        result = base_strategy.generate("any_metadata")
        assert isinstance(result, list)

    def test_generate_handles_none_metadata(self, base_strategy):
        """Should handle None metadata gracefully."""
        result = base_strategy.generate(None)
        assert isinstance(result, list)


