class TestStrategyIntegration:
    """Validates interaction between strategies and real-world scenarios."""

    def test_multiple_strategies_on_same_metadata(self, boundary_strategy, logic_branch_strategy, simple_metadata):
        """Both strategies should work independently on same metadata."""
        boundary_tests = boundary_strategy.generate(simple_metadata)
        logic_tests = logic_branch_strategy.generate(simple_metadata)
        
        assert len(boundary_tests) > 0
        assert len(logic_tests) == simple_metadata.branches
        # Test names should not overlap
        assert not set(boundary_tests) & set(logic_tests)

    def test_strategy_composition(self, boundary_strategy, logic_branch_strategy, complex_metadata):
        """Combined output should cover both edge cases and branches."""
        all_tests = (
            boundary_strategy.generate(complex_metadata) +
            logic_branch_strategy.generate(complex_metadata)
        )
        
        # Verify coverage
        test_string = " ".join(all_tests)
        assert "str_edge_case" in test_string or "int_edge_case" in test_string
        assert "branch_" in test_string

    def test_strategy_pattern_compliance(self, boundary_strategy, logic_branch_strategy):
        """Both strategies must conform to TestStrategy interface."""
        for strategy in [boundary_strategy, logic_branch_strategy]:
            assert isinstance(strategy, TestStrategy)
            result = strategy.generate(MockMetadata(name="test", args=["x"], branches=2))
            assert isinstance(result, list)
            assert all(isinstance(t, str) for t in result)


