class TestPerformance:
    """Validates strategy performance under load."""

    @pytest.mark.parametrize("num_args", [10, 50, 100])
    def test_boundary_strategy_scaling(self, boundary_strategy, num_args):
        """BoundaryStrategy should scale linearly with argument count."""
        metadata = MockMetadata(
            name="scaling_test",
            args=[f"arg_{i}" for i in range(num_args)]
        )
        import time
        start = time.perf_counter()
        tests = boundary_strategy.generate(metadata)
        elapsed = time.perf_counter() - start
        # Each arg generates ~12 tests (4 types × 3 values)
        expected_tests = num_args * 12
        assert len(tests) == expected_tests
        assert elapsed < 0.5  # Must complete within 500ms

    @pytest.mark.parametrize("num_branches", [100, 500, 1000])
    def test_logic_branch_strategy_scaling(self, logic_branch_strategy, num_branches):
        """LogicBranchStrategy should scale linearly with branch count."""
        metadata = MockMetadata(
            name="scaling_test",
            branches=num_branches
        )
        import time
        start = time.perf_counter()
        tests = logic_branch_strategy.generate(metadata)
        elapsed = time.perf_counter() - start
        assert len(tests) == num_branches
        assert elapsed < 0.5


